// one step out from the flagged account: account -USES-> identifier <-USES- account
MATCH (f:Account {id: 'A-3101'})-[:USES]->(x)<-[:USES]-(other:Account)
RETURN other.id AS account, x.id AS via;

// one, two and three steps: how many paths, and how many accounts, at each
MATCH (f:Account {id: 'A-3101'}) ((:Account)-[:USES]->(x)<-[:USES]-(:Account)){1,3} (other:Account)
WHERE other <> f
RETURN size(x) AS steps, count(*) AS paths, count(DISTINCT other) AS accounts
ORDER BY steps;

// what does A-1001 log in with? labels(x) says what kind of node x is
MATCH (a:Account {id: 'A-1001'})-[:USES]->(x)
RETURN labels(x)[0] AS kind, x.id AS id ORDER BY id;

// transfers of 900.00 or more: a property on the relationship
MATCH (from:Account)-[t:TRANSFERRED_TO]->(to:Account)
WHERE t.amountMinor >= 90000
RETURN from.id AS from, to.id AS to, t.amountMinor AS amountMinor ORDER BY amountMinor DESC;

// direction matters: who sent money TO A-1001?
MATCH (a:Account {id: 'A-1001'})<-[t:TRANSFERRED_TO]-(sender)
RETURN sender.id AS sender, t.amountMinor AS amountMinor ORDER BY sender;

// add a transfer, then read it back
MATCH (a:Account {id: 'A-4001'}), (b:Account {id: 'A-2002'})
CREATE (a)-[t:TRANSFERRED_TO {amountMinor: 2500}]->(b)
RETURN a.id AS from, type(t) AS rel, b.id AS to;

// money that comes back: 3 to 6 transfers that end where they started
MATCH p = (a:Account)-[:TRANSFERRED_TO]->{3,6}(a)
RETURN [n IN nodes(p) | n.id] AS cycle;

// the older syntax for the same walk (not GQL conformant, still everywhere in the wild)
MATCH p = (a:Account)-[:TRANSFERRED_TO*3..6]->(a)
RETURN count(p) AS paths;

// which identifiers do the most accounts share?
MATCH (x)<-[:USES]-(a:Account)
RETURN labels(x)[0] AS kind, x.id AS id, count(a) AS accounts
ORDER BY accounts DESC, id LIMIT 3;

PROFILE MATCH (f:Account {id: 'A-3101'})-[:USES]->(x)<-[:USES]-(other:Account)
